"use client";
import React, { useState, useEffect } from "react";
import { Search, SendHorizontal, Mail, ChevronRight, MessageSquare, ArrowUpRight } from "lucide-react";
import Link from "next/link"; // Assuming Next.js, use 'a' for standard React
import { faqData } from "@/data/faq"; 

export default function FAQPage() {
  const [activeId, setActiveId] = useState<string | null>(null);
  const [filter, setFilter] = useState<string>("All");
  const [searchQuery, setSearchQuery] = useState("");
  const [placeholderIndex, setPlaceholderIndex] = useState(0);

  const placeholders = [
    "SEARCH FOR SHIPPING...",
    "HOW DOES COD WORK?",
    "FIND YOUR FIT...",
    "RETURN POLICY DETAILS...",
    "TRACK YOUR DISPATCH..."
  ];

  // Auto-rotating placeholder effect
  useEffect(() => {
    const interval = setInterval(() => {
      setPlaceholderIndex((prev) => (prev + 1) % placeholders.length);
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  const filteredFaqs = faqData.filter((item) => {
    const matchesFilter = filter === "All" || item.category === filter;
    const matchesSearch = item.question.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesFilter && matchesSearch;
  });

  const categories = ["All", "Shipping", "Orders", "Returns", "Sizing", "Partnerships"];

  const handleGmailRedirect = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const question = formData.get("question") as string;
    const recipient = "support@fashionfriday.in";
    const subject = encodeURIComponent(`Inquiry: ${filter}`);
    const body = encodeURIComponent(`QUESTION:\n${question}\n\n---\nCategory: ${filter}`);
    window.location.href = `mailto:${recipient}?subject=${subject}&body=${body}`;
  };

  return (
    <div className="bg-background text-foreground min-h-screen pb-32 transition-colors duration-500">
      
      {/* 1. HEADER & SEARCH */}
      <section className="pt-32 pb-12 px-6">
        <div className="max-w-7xl mx-auto space-y-10">
          <div className="space-y-4">
            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-brand border-l-2 border-brand pl-4">
              Knowledge Base / 2026
            </span>
            <h1 className="text-6xl md:text-8xl font-black uppercase tracking-tighter italic leading-none">
              How can we <br /> <span className="text-foreground-subtle">assist?</span>
            </h1>
          </div>

          <div className="space-y-6">
            {/* SEARCH BOX WITH AUTO-UPDATE PLACEHOLDER */}
            <div className="relative group w-full max-w-3xl">
              <Search className="absolute left-6 top-1/2 -translate-y-1/2 opacity-30 group-focus-within:text-brand transition-colors" size={18} />
              <input 
                type="text" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder={placeholders[placeholderIndex]} 
                className="w-full bg-background-muted rounded-full py-6 pl-14 pr-6 border border-border focus:border-brand outline-none uppercase font-black tracking-widest text-[11px] transition-all placeholder:transition-opacity placeholder:duration-500"
              />
            </div>
            
            {/* SINGLE LINE SCROLLABLE TAGS */}
            <div className="w-full overflow-x-auto no-scrollbar pb-2">
              <div className="flex flex-nowrap gap-3 items-center">
                {categories.map((cat) => (
                  <button
                    key={cat}
                    onClick={() => setFilter(cat)}
                    className={`whitespace-nowrap px-8 py-4 rounded-full text-[9px] font-black uppercase tracking-widest border transition-all ${
                      filter === cat ? "bg-brand text-brand-foreground border-brand shadow-lg shadow-brand/20" : "bg-transparent border-border hover:border-brand"
                    }`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* 2. DYNAMIC FAQ LIST */}
      <section className="max-w-4xl mx-auto px-6 mb-24">
        {filteredFaqs.length > 0 ? (
          <div className="space-y-4">
            {filteredFaqs.map((faq) => (
              <div 
                key={faq.id}
                className={`rounded-[2.5rem] border transition-all duration-500 ${
                  activeId === faq.id ? "bg-background-muted border-brand shadow-xl" : "bg-background border-border"
                }`}
              >
                <button 
                  onClick={() => setActiveId(activeId === faq.id ? null : faq.id)}
                  className="w-full px-8 py-8 flex items-center justify-between text-left group"
                >
                   <h3 className="text-lg font-black uppercase tracking-tight italic group-hover:translate-x-2 transition-transform max-w-[80%]">
                    {faq.question}
                  </h3>
                  <div className={`p-2 rounded-full border border-border transition-all ${activeId === faq.id ? "rotate-90 bg-brand text-brand-foreground border-brand" : ""}`}>
                    <ChevronRight size={18} />
                  </div>
                </button>
                
                {activeId === faq.id && (
                  <div className="px-8 pb-10 animate-in slide-in-from-top-2">
                    <div className="border-t border-border pt-6 space-y-6">
                      <p className="text-foreground-muted leading-relaxed font-medium italic">
                        {faq.answer}
                      </p>
                      
                      {/* RELIABLE PAGE LINK SECTION */}
                      {faq.href && (
                        <Link 
                          href={faq.href}
                          className="inline-flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] text-brand hover:gap-4 transition-all"
                        >
                          Deep Dive into {faq.category} <ArrowUpRight size={14} />
                        </Link>
                      )}
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        ) : (
          <div className="py-20 text-center space-y-4 opacity-40">
            <MessageSquare className="mx-auto" size={40} />
            <p className="uppercase font-black tracking-widest text-xs italic">Archive node unreachable.</p>
          </div>
        )}
      </section>

      {/* 3. MINIMALIST DISPATCH NODE */}
      <section className="max-w-7xl mx-auto px-6">
        <div className="bg-background-muted rounded-[4rem] p-10 md:p-20 border border-border relative overflow-hidden">
          <div className="max-w-3xl mx-auto text-center space-y-12 relative z-10">
            <div className="space-y-6">
              <div className="inline-flex items-center gap-3 px-4 py-2 rounded-full bg-background border border-border mx-auto">
                <Mail className="text-brand" size={14} />
                <span className="text-[9px] font-black uppercase tracking-widest">Support Node</span>
              </div>
              <h2 className="text-4xl md:text-6xl font-black uppercase tracking-tighter italic leading-none">
                Still Need <span className="text-foreground-subtle">Answers?</span>
              </h2>
            </div>

            <div className="bg-background rounded-[3rem] p-4 border border-border shadow-2xl overflow-hidden">
              <form onSubmit={handleGmailRedirect}>
                <textarea 
                  required
                  name="question"
                  rows={3}
                  placeholder="DESCRIBE YOUR INQUIRY..." 
                  className="w-full bg-transparent rounded-[2.5rem] py-8 px-10 outline-none uppercase font-black tracking-widest text-[12px] resize-none transition-all placeholder:opacity-30"
                />
                <div className="flex items-center justify-between px-6 pb-4">
                  <span className="hidden sm:block text-[9px] font-black uppercase tracking-widest opacity-30 italic">
                    Department: {filter === "All" ? "General" : filter}
                  </span>
                  <button 
                    type="submit"
                    className="w-full sm:w-auto bg-brand text-brand-foreground px-10 py-5 rounded-full font-black uppercase tracking-[0.2em] text-[10px] hover:scale-105 active:scale-95 transition-all flex items-center justify-center gap-3"
                  >
                    Open Gmail <SendHorizontal size={14} />
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}